package imagehash

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"fmt"
	"math"
	"testing"
)

// Captured from actual installed Pillow 12.2.0 in fixed image333, using the
// installed Tjupt _tohash (ed717891d30abcac798407c8889776ec79191e447b4ef7f97aee1bddb0f98bb0).
// These are decoded TIFF pixels and exact resized L bytes, not decoder fixtures.
func TestActualPillowScalarSamples(t *testing.T) {
	cases := []struct {
		name, mode, pixels, hash string
		gray                     []byte
	}{
		{name: "tiff-F32-raw", mode: "F", pixels: "", hash: "0000111000100011110010000111001100001110110000111011100001111110000111011100001101111000110011100001", gray: []byte{0, 0, 0, 84, 170, 255, 255, 0, 0, 0, 255, 0, 0, 40, 127, 213, 255, 251, 0, 0, 255, 47, 0, 0, 80, 166, 254, 255, 25, 0, 255, 255, 0, 0, 35, 121, 207, 255, 255, 0, 246, 255, 96, 0, 0, 75, 161, 248, 255, 40, 201, 255, 255, 0, 0, 30, 116, 202, 255, 255, 155, 238, 255, 90, 0, 0, 70, 157, 244, 255, 109, 192, 255, 255, 0, 0, 25, 111, 199, 255, 63, 146, 233, 255, 155, 0, 0, 65, 153, 236, 19, 102, 190, 255, 255, 0, 0, 21, 109, 192}},
		{name: "tiff-I32-signed-raw", mode: "I", pixels: "", hash: "0111110001111110001001110000011110100011100101111000101111011101110110111110110001110100011010100000", gray: []byte{81, 255, 202, 208, 196, 255, 172, 175, 173, 255, 255, 196, 210, 197, 236, 167, 183, 177, 204, 109, 132, 216, 200, 224, 149, 189, 175, 190, 110, 206, 220, 200, 204, 141, 199, 166, 185, 101, 227, 255, 233, 178, 146, 203, 147, 206, 255, 242, 237, 143, 124, 162, 196, 127, 221, 255, 239, 208, 195, 255, 212, 196, 112, 244, 247, 228, 191, 213, 222, 165, 255, 206, 255, 230, 215, 183, 227, 202, 181, 141, 184, 255, 207, 207, 185, 233, 176, 176, 161, 255, 255, 185, 221, 179, 222, 155, 193, 161, 189, 98}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			p, err := base64.StdEncoding.DecodeString(c.pixels)
			if err != nil {
				t.Fatal(err)
			}
			before := append([]byte(nil), p...)
			r := Raster{Mode: c.mode, Width: 32, Height: 24, Pixels: p}
			got, err := Gray(r, [2]int{10, 10})
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, c.gray) {
				t.Fatalf("gray got %v want actual Pillow %v", got, c.gray)
			}
			hash, err := Raw(r, [2]int{10, 10})
			if err != nil {
				t.Fatal(err)
			}
			if hash != c.hash {
				t.Fatalf("hash got %s want actual installed %s", hash, c.hash)
			}
			if !bytes.Equal(p, before) {
				t.Fatal("input pixels changed")
			}
			if c.mode == "I" {
				// Actual Linux Pillow mode-I bytes, before Convert.c can hide a
				// rounding difference by clamping it to zero or 255.
				for shape, want := range map[[2]int]string{
					{10, 24}: "310ec474b5c96625dd2cc9146b68a7b4b29b9f496b0a410328969ae40d2094ed",
					{10, 10}: "8434d62567104c4cfc187fd32597c17f18ca19853412ad8e1a24f747b18a2065",
				} {
					got := fmt.Sprintf("%x", sha256.Sum256(resizeScalar(p, 32, 24, shape[0], shape[1], "I")))
					if got != want {
						t.Errorf("mode-I intermediate %v got SHA %s want actual %s", shape, got, want)
					}
				}
			}
		})
	}
}

// Resample.c ROUND_UP stores an integer after each pass: averaging this 2x2
// once would round 0.25 to zero, while two mode-I passes must produce one.
func TestScalarIntegerPassRounding(t *testing.T) {
	p := make([]byte, 16)
	binary.LittleEndian.PutUint32(p[4:], 1)
	got, err := Gray(Raster{Mode: "I", Width: 2, Height: 2, Pixels: p}, [2]int{1, 1})
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, []byte{1}) {
		t.Fatalf("got %v want two-pass ROUND_UP 1", got)
	}
}

// Convert.c clamps only the resized scalar; clamping the input first would
// average 255 and 0 instead of 1000 and -500 and produce a different result.
func TestScalarResizeBeforeClamp(t *testing.T) {
	for _, mode := range []string{"I", "F"} {
		t.Run(mode, func(t *testing.T) {
			p := make([]byte, 8)
			for i, v := range []float64{1000, -500} {
				if mode == "I" {
					binary.LittleEndian.PutUint32(p[i*4:], uint32(int32(v)))
				} else {
					binary.LittleEndian.PutUint32(p[i*4:], math.Float32bits(float32(v)))
				}
			}
			got, err := Gray(Raster{Mode: mode, Width: 2, Height: 1, Pixels: p}, [2]int{1, 1})
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, []byte{250}) {
				t.Fatalf("got %v want resize-before-convert 250", got)
			}
		})
	}
}

func TestScalarConversionBoundaries(t *testing.T) {
	cases := []struct {
		mode   string
		values []float64
		want   []byte
	}{
		{"I", []float64{-2147483648, -1, 0, 1, 254, 255, 2147483647}, []byte{0, 0, 0, 1, 254, 255, 255}},
		{"F", []float64{-100, -0.25, 0, 0.999, 1.999, 254.999, 255, 1000}, []byte{0, 0, 0, 0, 1, 254, 255, 255}},
	}
	for _, c := range cases {
		t.Run(c.mode, func(t *testing.T) {
			p := make([]byte, len(c.values)*4)
			for i, v := range c.values {
				if c.mode == "I" {
					binary.LittleEndian.PutUint32(p[i*4:], uint32(int32(v)))
				} else {
					binary.LittleEndian.PutUint32(p[i*4:], math.Float32bits(float32(v)))
				}
			}
			got, err := Gray(Raster{Mode: c.mode, Width: len(c.values), Height: 1, Pixels: p}, [2]int{len(c.values), 1})
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, c.want) {
				t.Fatalf("got %v want Convert.c L %v", got, c.want)
			}
		})
	}
}

func TestScalarFloatPassStorage(t *testing.T) {
	// Two exactly stored float32 inputs whose double average is between adjacent
	// float32 values. Each axis must write float32 before the next axis reads it.
	p := make([]byte, 8)
	binary.LittleEndian.PutUint32(p, math.Float32bits(math.Nextafter32(1, 2)))
	binary.LittleEndian.PutUint32(p[4:], math.Float32bits(2))
	got := resizeScalar(p, 2, 1, 1, 1, "F")
	if bits := binary.LittleEndian.Uint32(got); bits != math.Float32bits(1.5) {
		t.Fatalf("float32 pass stored %08x want 1.5", bits)
	}
}

func TestScalarInvalidRaster(t *testing.T) {
	for _, mode := range []string{"I", "F"} {
		if _, err := Gray(Raster{Mode: mode, Width: 2, Height: 1, Pixels: make([]byte, 7)}, [2]int{1, 1}); err != ErrInvalid {
			t.Fatalf("%s malformed bytes got %v", mode, err)
		}
	}
}

// Additional actual fixed333 Linux x86_64 Pillow results. In particular, its
// int32 resampler converts out-of-range ROUND_UP results to INT_MIN rather
// than saturating to INT_MAX as an ARM64 float-to-int instruction can do.
func TestActualPillowScalarBoundaries(t *testing.T) {
	cases := []struct {
		name, mode, pixels, resized, gray string
		w, h, ow, oh                      int
	}{
		{name: "I-2x2-one-quarter-to-1x1", mode: "I", pixels: "AAAAAAEAAAAAAAAAAAAAAA==", resized: "AQAAAA==", gray: "AQ==", w: 2, h: 2, ow: 1, oh: 1},
		{name: "F-specials-direct-L-no-resize", mode: "F", pixels: "AACA/wAAAABmZmY/ZuZ+QwAAf0MAAIB/AADAfw==", resized: "AACA/wAAAABmZmY/ZuZ+QwAAf0MAAIB/AADAfw==", gray: "AAAA/v//AA==", w: 7, h: 1, ow: 7, oh: 1},
		{name: "I-int32-extremes-checkerboard-min-first", mode: "I", pixels: "AAAAgP///3////9/AAAAgA==", resized: "", gray: "", w: 2, h: 2, ow: 17, oh: 17},
		{name: "I-int32-extremes-checkerboard-max-first", mode: "I", pixels: "////fwAAAIAAAACA////fw==", resized: "", gray: "", w: 2, h: 2, ow: 17, oh: 17},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			decode := func(s string) []byte {
				t.Helper()
				p, err := base64.StdEncoding.DecodeString(s)
				if err != nil {
					t.Fatal(err)
				}
				return p
			}
			p := decode(c.pixels)
			resized := resizeScalar(p, c.w, c.h, c.ow, c.oh, c.mode)
			if want := decode(c.resized); !bytes.Equal(resized, want) {
				t.Errorf("resized %s pixels differ from actual Linux Pillow", c.mode)
			}
			got, err := Gray(Raster{Mode: c.mode, Width: c.w, Height: c.h, Pixels: p}, [2]int{c.ow, c.oh})
			if err != nil {
				t.Fatal(err)
			}
			if want := decode(c.gray); !bytes.Equal(got, want) {
				t.Errorf("L got %v want actual Linux Pillow %v", got, want)
			}
		})
	}
}
